-- Hive SaaS identity core.
--
-- Stage only. Do not apply to production until the Clerk cutover negative tests
-- pass. This migration decouples public business ownership from auth.users while
-- preserving every existing UUID exactly.
--
-- Existing Supabase Auth user:
--   auth.users.id == app_users.id
--
-- New Clerk-only user:
--   app_users.id is generated by Hive and external_auth_identities maps the
--   trusted issuer+subject to that UUID.
--
-- This allows new SaaS users without manufacturing rows inside auth.users.

begin;

create table if not exists public.app_users (
  id uuid primary key default gen_random_uuid(),
  primary_email text not null default ''
    check (length(primary_email) <= 320),
  display_name text not null default ''
    check (length(display_name) <= 200),
  email_verified boolean not null default false,
  status text not null default 'active'
    check (status in ('active', 'disabled')),
  legacy_auth_user boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists app_users_email_idx
  on public.app_users(lower(primary_email))
  where primary_email <> '';

alter table public.app_users enable row level security;
revoke all on public.app_users from public, anon, authenticated;

-- Preserve all existing identity UUIDs 1:1.
insert into public.app_users(
  id,
  primary_email,
  display_name,
  email_verified,
  status,
  legacy_auth_user,
  created_at,
  updated_at
)
select
  account.id,
  lower(coalesce(account.email, '')),
  coalesce(
    nullif(trim((to_jsonb(account)->'raw_user_meta_data')->>'full_name'), ''),
    nullif(trim((to_jsonb(account)->'raw_user_meta_data')->>'name'), ''),
    split_part(coalesce(account.email, ''), '@', 1),
    ''
  ),
  nullif(to_jsonb(account)->>'email_confirmed_at', '') is not null,
  'active',
  true,
  coalesce(
    nullif(to_jsonb(account)->>'created_at', '')::timestamptz,
    now()
  ),
  now()
from auth.users account
on conflict (id) do update set
  primary_email = excluded.primary_email,
  display_name = excluded.display_name,
  email_verified = excluded.email_verified,
  legacy_auth_user = true,
  updated_at = now();

-- Evolve the staged Clerk bridge without destroying the legacy rollback link.
alter table public.external_auth_identities
  add column if not exists app_user_id uuid;

update public.external_auth_identities
set app_user_id = legacy_user_id
where app_user_id is null
  and legacy_user_id is not null;

alter table public.external_auth_identities
  drop constraint if exists external_auth_identities_app_user_id_fkey;

alter table public.external_auth_identities
  add constraint external_auth_identities_app_user_id_fkey
  foreign key (app_user_id)
  references public.app_users(id)
  on delete restrict;

alter table public.external_auth_identities
  alter column app_user_id set not null;

-- New Clerk-only users do not have a row in auth.users.
alter table public.external_auth_identities
  alter column legacy_user_id drop not null;

create index if not exists external_auth_identities_app_user_idx
  on public.external_auth_identities(app_user_id, active);

-- Repoint every PUBLIC foreign key that historically referenced auth.users(id)
-- to app_users(id). UUID values remain unchanged, so this is metadata-only for
-- existing business rows.
do $hive_repoint_auth_fks$
declare
  v_fk record;
  v_update text;
  v_delete text;
  v_deferrable text;
begin
  for v_fk in
    select
      constraint_row.conname,
      source_namespace.nspname as source_schema,
      source_table.relname as source_table,
      source_column.attname as source_column,
      constraint_row.confupdtype,
      constraint_row.confdeltype,
      constraint_row.condeferrable,
      constraint_row.condeferred
    from pg_constraint constraint_row
    join pg_class source_table
      on source_table.oid = constraint_row.conrelid
    join pg_namespace source_namespace
      on source_namespace.oid = source_table.relnamespace
    join pg_class target_table
      on target_table.oid = constraint_row.confrelid
    join pg_namespace target_namespace
      on target_namespace.oid = target_table.relnamespace
    join pg_attribute source_column
      on source_column.attrelid = source_table.oid
     and source_column.attnum = constraint_row.conkey[1]
    where constraint_row.contype = 'f'
      and source_namespace.nspname = 'public'
      and target_namespace.nspname = 'auth'
      and target_table.relname = 'users'
      and array_length(constraint_row.conkey, 1) = 1
      and array_length(constraint_row.confkey, 1) = 1
  loop
    v_update := case v_fk.confupdtype
      when 'r' then 'RESTRICT'
      when 'c' then 'CASCADE'
      when 'n' then 'SET NULL'
      when 'd' then 'SET DEFAULT'
      else 'NO ACTION'
    end;
    v_delete := case v_fk.confdeltype
      when 'r' then 'RESTRICT'
      when 'c' then 'CASCADE'
      when 'n' then 'SET NULL'
      when 'd' then 'SET DEFAULT'
      else 'NO ACTION'
    end;
    v_deferrable := case
      when not v_fk.condeferrable then 'NOT DEFERRABLE'
      when v_fk.condeferred then 'DEFERRABLE INITIALLY DEFERRED'
      else 'DEFERRABLE INITIALLY IMMEDIATE'
    end;

    execute format(
      'alter table %I.%I drop constraint %I',
      v_fk.source_schema,
      v_fk.source_table,
      v_fk.conname
    );

    execute format(
      'alter table %I.%I add constraint %I foreign key (%I) references public.app_users(id) on update %s on delete %s %s',
      v_fk.source_schema,
      v_fk.source_table,
      v_fk.conname,
      v_fk.source_column,
      v_update,
      v_delete,
      v_deferrable
    );
  end loop;
end;
$hive_repoint_auth_fks$;

-- The current actor now resolves to Hive's internal user UUID.
create or replace function public.current_app_user_id()
returns uuid
language plpgsql
stable
security definer
set search_path = pg_catalog, public, auth
as $hive_current_app_user$
declare
  v_claims jsonb := auth.jwt();
  v_subject text := nullif(v_claims ->> 'sub', '');
  v_issuer text := nullif(v_claims ->> 'iss', '');
  v_user uuid;
begin
  if v_subject is null then
    return null;
  end if;

  -- Legacy Supabase session: preserve the same UUID.
  begin
    v_user := v_subject::uuid;
    if exists (
      select 1
      from public.app_users account
      where account.id = v_user
        and account.status = 'active'
    ) then
      return v_user;
    end if;
  exception
    when invalid_text_representation then
      v_user := null;
  end;

  if v_issuer is null then
    return null;
  end if;

  select identity.app_user_id
    into v_user
  from public.external_auth_identities identity
  join public.app_users account
    on account.id = identity.app_user_id
  where identity.issuer = v_issuer
    and identity.subject = v_subject
    and identity.active
    and account.status = 'active'
  limit 1;

  return v_user;
end;
$hive_current_app_user$;

revoke all on function public.current_app_user_id() from public, anon;
grant execute on function public.current_app_user_id() to authenticated;

-- Provision a net-new user for the CURRENT trusted third-party subject.
-- p_email / p_display_name are profile metadata only; authorization never
-- depends on these values.
create or replace function public.provision_current_app_user(
  p_email text default '',
  p_display_name text default ''
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $hive_provision_app_user$
declare
  v_claims jsonb := auth.jwt();
  v_subject text := nullif(v_claims ->> 'sub', '');
  v_issuer text := nullif(v_claims ->> 'iss', '');
  v_provider text;
  v_existing uuid;
  v_user uuid;
begin
  if v_subject is null or v_issuer is null then
    raise exception 'third-party authentication required'
      using errcode = '42501';
  end if;

  -- A legacy Supabase UUID session must never create a second identity.
  begin
    v_existing := v_subject::uuid;
    if exists (select 1 from auth.users where id = v_existing) then
      insert into public.app_users(id, primary_email, display_name, email_verified, legacy_auth_user)
      values (
        v_existing,
        lower(left(trim(coalesce(p_email, '')), 320)),
        left(trim(coalesce(p_display_name, '')), 200),
        false,
        true
      )
      on conflict (id) do nothing;
      return v_existing;
    end if;
  exception
    when invalid_text_representation then
      v_existing := null;
  end;

  select trusted.provider
    into v_provider
  from public.trusted_external_auth_issuers trusted
  where trusted.issuer = v_issuer
    and trusted.active
  limit 1;

  if v_provider is null then
    raise exception 'untrusted identity issuer'
      using errcode = '42501';
  end if;

  select identity.app_user_id
    into v_existing
  from public.external_auth_identities identity
  where identity.issuer = v_issuer
    and identity.subject = v_subject
    and identity.active
  limit 1;

  if v_existing is not null then
    return v_existing;
  end if;

  insert into public.app_users(
    primary_email,
    display_name,
    email_verified,
    legacy_auth_user
  )
  values (
    lower(left(trim(coalesce(p_email, '')), 320)),
    left(trim(coalesce(p_display_name, '')), 200),
    false,
    false
  )
  returning id into v_user;

  insert into public.external_auth_identities(
    issuer,
    subject,
    legacy_user_id,
    app_user_id,
    provider,
    active
  )
  values (
    v_issuer,
    v_subject,
    null,
    v_user,
    v_provider,
    true
  );

  return v_user;
end;
$hive_provision_app_user$;

revoke all on function public.provision_current_app_user(text, text)
  from public, anon;
grant execute on function public.provision_current_app_user(text, text)
  to authenticated;

-- Identity-link redemption now targets app_users. Existing migration codes
-- still link to the same UUID because all legacy app_users were seeded 1:1.
create or replace function public.claim_external_identity_link_token(p_token text)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public, auth, extensions
as $hive_claim_identity_link_app_user$
declare
  v_claims jsonb := auth.jwt();
  v_subject text := nullif(v_claims ->> 'sub', '');
  v_issuer text := nullif(v_claims ->> 'iss', '');
  v_provider text;
  v_user uuid;
  v_existing uuid;
begin
  if v_subject is null or v_issuer is null then
    raise exception 'third-party authentication required'
      using errcode = '42501';
  end if;

  select trusted.provider
    into v_provider
  from public.trusted_external_auth_issuers trusted
  where trusted.issuer = v_issuer
    and trusted.active
  limit 1;

  if v_provider is null then
    raise exception 'untrusted identity issuer'
      using errcode = '42501';
  end if;

  if p_token is null
     or length(p_token) <> 69
     or left(p_token, 5) <> 'hive_' then
    raise exception 'invalid or expired identity link code'
      using errcode = '22023';
  end if;

  select link.legacy_user_id
    into v_user
  from public.external_auth_identity_link_tokens link
  where link.token_hash =
        encode(extensions.digest(p_token, 'sha256'), 'hex')
    and link.used_at is null
    and link.expires_at > now()
  for update;

  if v_user is null
     or not exists (select 1 from public.app_users where id = v_user) then
    raise exception 'invalid or expired identity link code'
      using errcode = '22023';
  end if;

  select identity.app_user_id
    into v_existing
  from public.external_auth_identities identity
  where identity.issuer = v_issuer
    and identity.subject = v_subject
  limit 1;

  if v_existing is not null and v_existing <> v_user then
    raise exception 'identity is already linked to another account'
      using errcode = '23505';
  end if;

  insert into public.external_auth_identities(
    issuer,
    subject,
    legacy_user_id,
    app_user_id,
    provider,
    active
  )
  values (
    v_issuer,
    v_subject,
    case
      when exists (select 1 from auth.users where id = v_user)
      then v_user
      else null
    end,
    v_user,
    v_provider,
    true
  )
  on conflict (issuer, subject)
  do update set
    app_user_id = excluded.app_user_id,
    legacy_user_id = excluded.legacy_user_id,
    active = true,
    provider = excluded.provider,
    updated_at = now();

  update public.external_auth_identity_link_tokens
     set used_at = now()
   where legacy_user_id = v_user
     and token_hash =
         encode(extensions.digest(p_token, 'sha256'), 'hex')
     and used_at is null;

  return v_user;
end;
$hive_claim_identity_link_app_user$;

revoke all on function public.claim_external_identity_link_token(text)
  from public, anon;
grant execute on function public.claim_external_identity_link_token(text)
  to authenticated;

-- Workspace creation/profile lookup must no longer depend on auth.users.
create or replace function public.create_hive_preview_workspace(
  p_name text,
  p_invoice_prefix text default 'HIVE'
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public
as $hive_create_preview_workspace_app_user$
declare
  v_user uuid := public.current_app_user_id();
  v_workspace uuid;
  v_name text := trim(coalesce(p_name, ''));
  v_slug_base text;
  v_slug text;
  v_prefix text := upper(trim(coalesce(p_invoice_prefix, 'HIVE')));
  v_profile public.app_users%rowtype;
begin
  if v_user is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select * into v_profile
  from public.app_users
  where id = v_user
    and status = 'active';

  if not found then
    raise exception 'mapped Hive user does not exist';
  end if;

  if length(v_name) < 2 or length(v_name) > 120 then
    raise exception 'business name must contain 2 to 120 characters';
  end if;

  if v_prefix !~ '^[A-Z0-9-]{1,12}$' then
    raise exception 'invalid invoice prefix';
  end if;

  v_slug_base := lower(regexp_replace(v_name, '[^A-Za-z0-9]+', '-', 'g'));
  v_slug_base := regexp_replace(v_slug_base, '(^-+|-+$)', '', 'g');
  if v_slug_base = '' then v_slug_base := 'business'; end if;
  v_slug_base := left(v_slug_base, 70);
  v_slug := 'hive-dev-' || v_slug_base || '-' ||
    left(replace(gen_random_uuid()::text, '-', ''), 8);

  insert into public.workspaces(owner_id, name, slug, status)
  values (v_user, v_name, v_slug, 'active')
  returning id into v_workspace;

  insert into public.workspace_memberships(workspace_id, user_id, role)
  values (v_workspace, v_user, 'owner');

  insert into public.workspace_settings(
    workspace_id,
    business_name,
    legal_name,
    contact_name,
    email,
    invoice_sender_name,
    invoice_prefix,
    currency,
    country
  )
  values (
    v_workspace,
    v_name,
    v_name,
    v_profile.display_name,
    v_profile.primary_email,
    v_name,
    v_prefix,
    'CHF',
    'Schweiz'
  );

  return v_workspace;
end;
$hive_create_preview_workspace_app_user$;

revoke all on function public.create_hive_preview_workspace(text, text)
  from public, anon;
grant execute on function public.create_hive_preview_workspace(text, text)
  to authenticated;

create or replace function public.list_workspace_members(p_workspace_id uuid)
returns table(
  membership_id uuid,
  user_id uuid,
  role public.workspace_role,
  email text,
  display_name text,
  created_at timestamptz
)
language plpgsql
stable
security definer
set search_path = pg_catalog, public
as $hive_list_members_app_users$
begin
  if not public.is_workspace_member(p_workspace_id, 'admin') then
    raise exception 'workspace admin access required'
      using errcode = '42501';
  end if;

  return query
    select
      membership.id,
      membership.user_id,
      membership.role,
      account.primary_email,
      coalesce(
        nullif(trim(account.display_name), ''),
        split_part(account.primary_email, '@', 1)
      ),
      membership.created_at
    from public.workspace_memberships membership
    join public.app_users account
      on account.id = membership.user_id
    where membership.workspace_id = p_workspace_id
    order by
      case membership.role
        when 'owner' then 1
        when 'admin' then 2
        when 'accountant' then 3
        else 4
      end,
      membership.created_at;
end;
$hive_list_members_app_users$;

revoke all on function public.list_workspace_members(uuid) from public, anon;
grant execute on function public.list_workspace_members(uuid) to authenticated;

-- Existing by-email management now resolves only VERIFIED Hive profile email
-- addresses. New third-party users are not considered verified merely because
-- a caller supplied p_email to the provisioning RPC. A future invitation flow
-- should authorize using its own one-time invite token, not profile text.
create or replace function public.add_workspace_member_by_email(
  p_workspace_id uuid,
  p_email text,
  p_role public.workspace_role
)
returns uuid
language plpgsql
security definer
set search_path = pg_catalog, public
as $hive_add_member_app_user$
declare
  v_target uuid;
  v_membership uuid;
  v_email text := lower(trim(coalesce(p_email, '')));
begin
  if not public.is_workspace_member(p_workspace_id, 'owner') then
    raise exception 'workspace owner access required'
      using errcode = '42501';
  end if;
  if p_role = 'owner' then
    raise exception 'owner role cannot be assigned';
  end if;
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'invalid email';
  end if;

  select id into v_target
  from public.app_users
  where lower(primary_email) = v_email
    and email_verified
    and status = 'active'
  order by created_at
  limit 1;

  if v_target is null then
    raise exception 'user must create a Hive account before being added';
  end if;

  if exists (
    select 1
    from public.workspaces workspace
    where workspace.id = p_workspace_id
      and workspace.owner_id = v_target
  ) then
    raise exception 'workspace owner role cannot be changed';
  end if;

  insert into public.workspace_memberships(workspace_id, user_id, role)
  values (p_workspace_id, v_target, p_role)
  on conflict (workspace_id, user_id)
  do update set role = excluded.role, updated_at = now()
  returning id into v_membership;

  return v_membership;
end;
$hive_add_member_app_user$;

revoke all on function public.add_workspace_member_by_email(
  uuid, text, public.workspace_role
) from public, anon;
grant execute on function public.add_workspace_member_by_email(
  uuid, text, public.workspace_role
) to authenticated;

commit;
